function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extra-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function write(root, name, bytes = Buffer.from([0, 255, 10])) {
  fs.mkdirSync(path.dirname(path.join(root, name)), {recursive:true});
  fs.writeFileSync(path.join(root, name), bytes);
  fs.chmodSync(path.join(root, name), 0o640);
}
const cli = (...args) => spawnSync(process.execPath, [script, ...args], {encoding:'utf8'});

test('all drift categories, reason order, string order and immutable inputs', t => {
  const root = fixture(t);
  const names = ['z', 'a', 'Z', 'é', 'space tab\tnewline\n', 'gone/file', 'link/file', 'blocked/file', 'directory', 'size'];
  names.forEach(name => write(root, name));
  const manifest = createManifest(root, Object.freeze(names));
  manifest.files.reverse();
  manifest.files.find(entry => entry.path === 'size').size++;
  manifest.files.forEach(Object.freeze);
  Object.freeze(manifest.files);
  Object.freeze(manifest);
  const before = JSON.stringify(manifest);
  fs.writeFileSync(path.join(root, 'z'), 'new bytes');
  fs.chmodSync(path.join(root, 'z'), 0o600);
  fs.chmodSync(path.join(root, 'a'), 0o600);
  fs.rmSync(path.join(root, 'gone'), {recursive:true});
  fs.rmSync(path.join(root, 'link'), {recursive:true});
  fs.symlinkSync(root, path.join(root, 'link'));
  fs.rmSync(path.join(root, 'blocked'), {recursive:true});
  write(root, 'blocked');
  fs.unlinkSync(path.join(root, 'directory'));
  fs.mkdirSync(path.join(root, 'directory'));
  write(root, 'unselected');
  assert.deepEqual(verifyManifest(root, manifest), {
    ok:false, unchanged:['Z', 'space tab\tnewline\n', 'é'],
    changed:[{path:'a', reasons:['mode']}, {path:'size', reasons:['content']}, {path:'z', reasons:['content', 'mode']}],
    missing:['gone/file'], unsafe:['blocked/file', 'directory', 'link/file'],
  });
  assert.equal(JSON.stringify(manifest), before);
});

test('complete manifest validation and root validation', t => {
  const root = fixture(t);
  write(root, 'a');
  const entry = createManifest(root, ['a']).files[0];
  for (const value of [null, [], {}, {version:2, files:[]}, {version:1, files:{}},
    {version:1, files:[entry, entry]}, {version:1, files:[null]}, {version:1, files:[[]]}]) {
    assert.throws(() => verifyManifest(root, value), Error);
  }
  for (const selected of ['', '/a', 'a\\b', 'a\0', 'a//b', './a', 'a/../b', 'a/']) {
    assert.throws(() => createManifest(root, [selected]), Error);
    assert.throws(() => verifyManifest(root, {version:1, files:[{...entry, path:selected}]}), Error);
  }
  for (const [key, values] of Object.entries({sha256:['A'.repeat(64), '0'.repeat(64) + '\n', '', 0],
    size:[-1, 0.5, Number.MAX_SAFE_INTEGER + 1, NaN, '3'], mode:[-1, 512, 1.5, '0']})) {
    for (const value of values) {
      assert.throws(() => verifyManifest(root, {version:1, files:[{...entry, [key]:value}]}), Error);
    }
  }
  assert.deepEqual(verifyManifest(root, {version:1, files:[], extra:true}),
    {ok:true, unchanged:[], changed:[], missing:[], unsafe:[]});
  fs.symlinkSync(root, path.join(root, 'alias'));
  for (const badRoot of ['', path.join(root, 'absent'), path.join(root, 'a'), path.join(root, 'alias'), path.join(root, 'alias') + '/']) {
    assert.throws(() => createManifest(badRoot, []), Error);
    assert.throws(() => verifyManifest(badRoot, {version:1, files:[]}), Error);
  }
  fs.symlinkSync(path.join(root, 'absent'), path.join(root, 'dangling'));
  assert.deepEqual(verifyManifest(root, {version:1, files:[{...entry, path:'dangling'}]}).unsafe, ['dangling']);
  assert.throws(() => createManifest(root, ['dangling']), Error);
});

test('CLI JSON framing, exit codes and silent imports', t => {
  const root = fixture(t);
  write(root, 'a');
  const created = cli('create', root, 'a');
  assert.equal(created.status, 0);
  assert.equal(created.stderr, '');
  assert.equal(created.stdout, JSON.stringify(createManifest(root, ['a'])) + '\n');
  const manifestFile = path.join(root, 'manifest.json');
  fs.writeFileSync(manifestFile, created.stdout);
  let verified = cli('verify', root, manifestFile);
  assert.equal(verified.status, 0);
  assert.equal(verified.stderr, '');
  assert.equal(verified.stdout, JSON.stringify(verifyManifest(root, JSON.parse(created.stdout))) + '\n');
  write(root, 'a', 'different');
  verified = cli('verify', root, manifestFile);
  assert.equal(verified.status, 1);
  assert.equal(verified.stderr, '');
  assert.equal(JSON.parse(verified.stdout).ok, false);
  fs.writeFileSync(path.join(root, 'bad.json'), '{');
  fs.writeFileSync(path.join(root, 'invalid.json'), '{}');
  for (const args of [[], ['other', root], ['create'], ['create', root, '../a'],
    ['verify', root], ['verify', root, manifestFile, 'extra'], ['verify', root, root],
    ['verify', root, path.join(root, 'absent')], ['verify', root, path.join(root, 'bad.json')],
    ['verify', root, path.join(root, 'invalid.json')]]) {
    const result = cli(...args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length);
  }
  const imported = spawnSync(process.execPath, ['--input-type=module', '-e', "import './snapshot.js'"], {encoding:'utf8'});
  assert.equal(imported.status, 0);
  assert.equal(imported.stdout, '');
  assert.equal(imported.stderr, '');
});

