import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import assert from 'node:assert/strict';import test from 'node:test';import {spawnSync} from 'node:child_process';
import {createManifest,verifyManifest} from './snapshot.js';
const temp=t=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'snapshot-review-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));return root;};
test('digest must reject a terminal newline',t=>{const root=temp(t);fs.writeFileSync(root+'/a','data');const m=createManifest(root,['a']);m.files[0].sha256+='\n';assert.throws(()=>verifyManifest(root,m));});
test('root must reject a missing component before dot-dot',t=>{const root=temp(t);assert.throws(()=>createManifest(root+'/missing/..',[]));assert.throws(()=>verifyManifest(root+'/missing/..',{version:1,files:[]}));});
test('root follows actual filesystem identity through an ancestor symlink and dot-dot',t=>{const root=temp(t);fs.mkdirSync(root+'/parent');fs.mkdirSync(root+'/elsewhere/nested',{recursive:true});fs.symlinkSync(root+'/elsewhere/nested',root+'/parent/link');fs.writeFileSync(root+'/parent/a','lexical directory');fs.writeFileSync(root+'/elsewhere/a','actual directory');const actual=createManifest(root+'/elsewhere',['a']),aliased=createManifest(root+'/parent/link/..',['a']);assert.deepEqual(aliased,actual);assert.equal(verifyManifest(root+'/parent/link/..',actual).ok,true);});
test('POSIX root may end in a literal backslash',t=>{const root=temp(t),dir=root+'/literal\\';fs.mkdirSync(dir);fs.writeFileSync(dir+'/a','data');const m=createManifest(dir,['a']);assert.equal(verifyManifest(dir,m).ok,true);});
test('filesystem root accepts repeated slash separators with empty selections',()=>{assert.deepEqual(createManifest('////',[]),{version:1,files:[]});assert.deepEqual(verifyManifest('////',{version:1,files:[]}),{ok:true,unchanged:[],changed:[],missing:[],unsafe:[]});});
test('CLI executes from a directory containing hash percent and spaces',t=>{const root=temp(t),dir=root+'/code # % space';fs.mkdirSync(dir);fs.copyFileSync('snapshot.js',dir+'/snapshot.mjs');fs.writeFileSync(root+'/a','data');const r=spawnSync(process.execPath,[dir+'/snapshot.mjs','create',root,'a'],{encoding:'utf8'});assert.equal(r.status,0,r.stderr);assert.equal(r.stderr,'');assert.equal(r.stdout,JSON.stringify(createManifest(root,['a']))+'\n');});
